1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseFrontmatter } from './frontmatter';
4	import { renderMarkdown, renderIndexBodyHtml } from './render';
5	import { TemplateEngine } from './templates';
6	import type { Page } from './types';
7	
8	export interface BuildOptions {
9	  contentDir: string;
10	  outputDir: string;
11	  /** Directory containing layouts/ and partials/ subdirectories. Defaults to ./templates relative to the current working directory. */
12	  templatesDir?: string;
13	}
14	
15	export interface BuildResult {
16	  pages: Page[];
17	  outputDir: string;
18	}
19	
20	const INDEX_LAYOUT_NAME = 'index';
21	
22	export function build(options: BuildOptions): BuildResult {
23	  const { contentDir, outputDir } = options;
24	  const templatesDir = options.templatesDir ?? path.resolve(process.cwd(), 'templates');
25	
26	  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
27	    throw new Error(`Content directory not found: ${contentDir}`);
28	  }
29	
30	  const engine = new TemplateEngine(templatesDir);
31	
32	  const markdownFiles = findMarkdownFiles(contentDir);
33	  const pages = markdownFiles.map((filePath) => buildPage(filePath, contentDir));
34	  pages.sort(comparePages);
35	
36	  fs.mkdirSync(outputDir, { recursive: true });
37	
38	  for (const page of pages) {
39	    const outPath = path.join(outputDir, page.outputFile);
40	    fs.mkdirSync(path.dirname(outPath), { recursive: true });
41	    const html = engine.render(page.layout, {
42	      title: page.title,
43	      date: page.date,
44	      tags: page.tags,
45	      body: page.html,
46	    });
47	    fs.writeFileSync(outPath, html, 'utf8');
48	  }
49	
50	  const indexLayout = engine.hasLayout(INDEX_LAYOUT_NAME) ? INDEX_LAYOUT_NAME : undefined;
51	  const indexHtml = engine.render(indexLayout, {
52	    title: 'All Pages',
53	    tags: [],
54	    body: renderIndexBodyHtml(pages),
55	  });
56	  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf8');
57	
58	  return { pages, outputDir };
59	}
60	
61	function comparePages(a: Page, b: Page): number {
62	  if (a.date && b.date) return b.date.localeCompare(a.date);
63	  if (a.date) return -1;
64	  if (b.date) return 1;
65	  return a.title.localeCompare(b.title);
66	}
67	
68	function findMarkdownFiles(dir: string): string[] {
69	  const entries = fs.readdirSync(dir, { withFileTypes: true });
70	  const files: string[] = [];
71	
72	  for (const entry of entries) {
73	    const fullPath = path.join(dir, entry.name);
74	    if (entry.isDirectory()) {
75	      files.push(...findMarkdownFiles(fullPath));
76	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
77	      files.push(fullPath);
78	    }
79	  }
80	
81	  return files;
82	}
83	
84	function buildPage(filePath: string, contentDir: string): Page {
85	  const raw = fs.readFileSync(filePath, 'utf8');
86	  const { data, content } = parseFrontmatter(raw);
87	  const html = renderMarkdown(content);
88	
89	  const relativePath = path.relative(contentDir, filePath);
90	  const slug = slugify(relativePath);
91	  const title = typeof data.title === 'string' && data.title.trim() ? data.title : slug;
92	  const date = typeof data.date === 'string' && data.date.trim() ? data.date : undefined;
93	  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
94	  const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : undefined;
95	
96	  return {
97	    slug,
98	    title,
99	    date,
100	    tags,
101	    html,
102	    sourcePath: relativePath,
103	    outputFile: `${slug}.html`,
104	    layout,
105	  };
106	}
107	
108	function slugify(relativePath: string): string {
109	  const withoutExt = relativePath.replace(/\.md$/i, '');
110	  const slug = withoutExt
111	    .split(path.sep)
112	    .join('-')
113	    .toLowerCase()
114	    .replace(/[^a-z0-9-]+/g, '-')
115	    .replace(/-+/g, '-')
116	    .replace(/^-|-$/g, '');
117	
118	  // "index" is reserved for the generated listing page.
119	  if (!slug || slug === 'index') return slug === 'index' ? 'index-page' : 'page';
120	  return slug;
121	}
