1	#!/usr/bin/env node
2	import { Command } from 'commander';
3	import * as path from 'path';
4	import { build } from './generator';
5	import { serve } from './serve';
6	
7	export function createCli(): Command {
8	  const program = new Command();
9	
10	  program
11	    .name('ssg')
12	    .description('A static site generator for Markdown content');
13	
14	  program
15	    .command('build')
16	    .description('Generate the static site')
17	    .option('--content <dir>', 'content directory to read Markdown files from', './content')
18	    .option('--output <dir>', 'output directory to write the generated site to', './dist')
19	    .option('--templates <dir>', 'templates directory containing layouts/ and partials/', './templates')
20	    .action((opts: { content: string; output: string; templates: string }) => {
21	      const contentDir = path.resolve(process.cwd(), opts.content);
22	      const outputDir = path.resolve(process.cwd(), opts.output);
23	      const templatesDir = path.resolve(process.cwd(), opts.templates);
24	      const result = build({ contentDir, outputDir, templatesDir });
25	      // eslint-disable-next-line no-console
26	      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
27	    });
28	
29	  program
30	    .command('serve')
31	    .description('Build the site, then serve it with live reload while watching for changes')
32	    .option('--content <dir>', 'content directory to read Markdown files from', './content')
33	    .option('--output <dir>', 'output directory to write the generated site to', './dist')
34	    .option('--templates <dir>', 'templates directory containing layouts/ and partials/', './templates')
35	    .option('--port <port>', 'port to serve the dev server on', '3000')
36	    .action(async (opts: { content: string; output: string; templates: string; port: string }) => {
37	      const contentDir = path.resolve(process.cwd(), opts.content);
38	      const outputDir = path.resolve(process.cwd(), opts.output);
39	      const templatesDir = path.resolve(process.cwd(), opts.templates);
40	      const port = Number(opts.port);
41	      const handle = await serve({ contentDir, outputDir, templatesDir, port });
42	      // eslint-disable-next-line no-console
43	      console.log(`Dev server running at ${handle.url}`);
44	      // eslint-disable-next-line no-console
45	      console.log(`Watching ${opts.content} and ${opts.templates} for changes...`);
46	    });
47	
48	  return program;
49	}
50	
51	export function run(argv: string[]): void {
52	  createCli().parse(argv);
53	}
54	
55	if (require.main === module) {
56	  run(process.argv);
57	}
