1	import { marked } from 'marked';
2	import type { Page } from './types';
3	
4	export function renderMarkdown(markdown: string): string {
5	  return marked.parse(markdown, { async: false }) as string;
6	}
7	
8	function escapeHtml(value: string): string {
9	  return value
10	    .replace(/&/g, '&amp;')
11	    .replace(/</g, '&lt;')
12	    .replace(/>/g, '&gt;')
13	    .replace(/"/g, '&quot;');
14	}
15	
16	function renderTags(tags: string[]): string {
17	  if (tags.length === 0) return '';
18	  const items = tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
19	  return `<div class="tags">${items}</div>`;
20	}
21	
22	/**
23	 * Builds the inner listing markup for the generated index page. This is
24	 * injected into the `index` (or `default`) layout's `{{{body}}}` placeholder
25	 * by the template engine, so it is plain HTML rather than a full document.
26	 */
27	export function renderIndexBodyHtml(pages: Page[]): string {
28	  const items = pages
29	    .map((page) => {
30	      const dateHtml = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
31	      return `    <li>
32	      <a href="${escapeHtml(page.outputFile)}">${escapeHtml(page.title)}</a>${dateHtml}
33	      ${renderTags(page.tags)}
34	    </li>`;
35	    })
36	    .join('\n');
37	
38	  return `<ul>
39	${items}
40	  </ul>`;
41	}
