1	import * as fs from 'fs';
2	import * as http from 'http';
3	import * as path from 'path';
4	import chokidar from 'chokidar';
5	import { WebSocket, WebSocketServer } from 'ws';
6	import { build } from './generator';
7	import type { BuildOptions } from './generator';
8	
9	export interface ServeOptions extends BuildOptions {
10	  /** Port to listen on. Use 0 to let the OS assign an ephemeral port. Defaults to 3000. */
11	  port?: number;
12	  /** Delay (ms) between a watched file change and the triggered rebuild, to coalesce bursts of changes. */
13	  debounceMs?: number;
14	}
15	
16	export interface ServeHandle {
17	  port: number;
18	  url: string;
19	  close(): Promise<void>;
20	}
21	
22	const DEFAULT_PORT = 3000;
23	const DEFAULT_DEBOUNCE_MS = 100;
24	const LIVERELOAD_PATH = '/__livereload';
25	
26	const MIME_TYPES: Record<string, string> = {
27	  '.html': 'text/html; charset=utf-8',
28	  '.css': 'text/css; charset=utf-8',
29	  '.js': 'text/javascript; charset=utf-8',
30	  '.json': 'application/json; charset=utf-8',
31	  '.svg': 'image/svg+xml',
32	  '.png': 'image/png',
33	  '.jpg': 'image/jpeg',
34	  '.jpeg': 'image/jpeg',
35	  '.gif': 'image/gif',
36	  '.ico': 'image/x-icon',
37	  '.txt': 'text/plain; charset=utf-8',
38	  '.xml': 'application/xml; charset=utf-8',
39	};
40	
41	function liveReloadScript(): string {
42	  return `<script>
43	(function () {
44	  var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
45	  var socket = new WebSocket(protocol + '//' + window.location.host + '${LIVERELOAD_PATH}');
46	  socket.addEventListener('message', function (event) {
47	    if (event.data === 'reload') {
48	      window.location.reload();
49	    }
50	  });
51	})();
52	</script>`;
53	}
54	
55	function injectLiveReload(html: string): string {
56	  const script = liveReloadScript();
57	  if (/<\/body>/i.test(html)) {
58	    return html.replace(/<\/body>/i, `${script}\n</body>`);
59	  }
60	  return `${html}\n${script}`;
61	}
62	
63	/** Resolves a request path to a file within rootDir, refusing to escape it via `..` traversal. */
64	function resolveServablePath(rootDir: string, urlPath: string): string | undefined {
65	  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
66	  let filePath = path.normalize(path.join(rootDir, decoded));
67	
68	  if (filePath !== rootDir && !filePath.startsWith(rootDir + path.sep)) {
69	    return undefined;
70	  }
71	
72	  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
73	    filePath = path.join(filePath, 'index.html');
74	  }
75	
76	  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
77	    return undefined;
78	  }
79	
80	  return filePath;
81	}
82	
83	function requestListener(outputDir: string): http.RequestListener {
84	  return (req, res) => {
85	    const filePath = resolveServablePath(outputDir, req.url ?? '/');
86	
87	    if (!filePath) {
88	      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
89	      res.end('Not found');
90	      return;
91	    }
92	
93	    const ext = path.extname(filePath).toLowerCase();
94	    const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
95	
96	    if (ext === '.html') {
97	      const html = fs.readFileSync(filePath, 'utf8');
98	      res.writeHead(200, { 'Content-Type': contentType });
99	      res.end(injectLiveReload(html));
100	      return;
101	    }
102	
103	    res.writeHead(200, { 'Content-Type': contentType });
104	    fs.createReadStream(filePath).pipe(res);
105	  };
106	}
107	
108	/**
109	 * Starts a dev server that serves the built site from `outputDir`, rebuilds
110	 * whenever `contentDir` or `templatesDir` change, and pushes a live-reload
111	 * notification over WebSocket to connected pages so browsers refresh
112	 * automatically once the rebuild completes.
113	 */
114	export function serve(options: ServeOptions): Promise<ServeHandle> {
115	  const { contentDir, outputDir } = options;
116	  const templatesDir = options.templatesDir ?? path.resolve(process.cwd(), 'templates');
117	  const debounceMs = options.debounceMs ?? DEFAULT_DEBOUNCE_MS;
118	
119	  build({ contentDir, outputDir, templatesDir });
120	
121	  const clients = new Set<WebSocket>();
122	  const wss = new WebSocketServer({ noServer: true });
123	  const httpServer = http.createServer(requestListener(outputDir));
124	
125	  httpServer.on('upgrade', (req, socket, head) => {
126	    if (req.url !== LIVERELOAD_PATH) {
127	      socket.destroy();
128	      return;
129	    }
130	    wss.handleUpgrade(req, socket, head, (ws) => {
131	      clients.add(ws);
132	      ws.on('close', () => clients.delete(ws));
133	    });
134	  });
135	
136	  function broadcastReload(): void {
137	    for (const client of clients) {
138	      if (client.readyState === WebSocket.OPEN) {
139	        client.send('reload');
140	      }
141	    }
142	  }
143	
144	  let rebuildTimer: ReturnType<typeof setTimeout> | undefined;
145	  function scheduleRebuild(): void {
146	    if (rebuildTimer) clearTimeout(rebuildTimer);
147	    rebuildTimer = setTimeout(() => {
148	      rebuildTimer = undefined;
149	      try {
150	        build({ contentDir, outputDir, templatesDir });
151	        broadcastReload();
152	      } catch (err) {
153	        // eslint-disable-next-line no-console
154	        console.error('Rebuild failed:', err instanceof Error ? err.message : err);
155	      }
156	    }, debounceMs);
157	  }
158	
159	  const watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });
160	  watcher.on('add', scheduleRebuild);
161	  watcher.on('change', scheduleRebuild);
162	  watcher.on('unlink', scheduleRebuild);
163	
164	  const watcherReady = new Promise<void>((resolve) => watcher.once('ready', resolve));
165	  const listening = new Promise<number>((resolve, reject) => {
166	    httpServer.once('error', reject);
167	    httpServer.listen(options.port ?? DEFAULT_PORT, () => {
168	      httpServer.removeListener('error', reject);
169	      const address = httpServer.address();
170	      resolve(typeof address === 'object' && address ? address.port : (options.port ?? DEFAULT_PORT));
171	    });
172	  });
173	
174	  return Promise.all([listening, watcherReady]).then(([port]) => ({
175	    port,
176	    url: `http://localhost:${port}`,
177	    close(): Promise<void> {
178	      if (rebuildTimer) clearTimeout(rebuildTimer);
179	      for (const client of clients) client.terminate();
180	      return watcher.close().then(
181	        () =>
182	          new Promise<void>((resolveClose, rejectClose) => {
183	            wss.close(() => {
184	              httpServer.close((err) => {
185	                if (err) rejectClose(err);
186	                else resolveClose();
187	              });
188	            });
189	          })
190	      );
191	    },
192	  }));
193	}
