1	import * as fs from 'fs';
2	import * as os from 'os';
3	import * as path from 'path';
4	import { build } from '../src/generator';
5	
6	function makeTempDir(prefix: string): string {
7	  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
8	}
9	
10	function writeFile(filePath: string, content: string): void {
11	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
12	  fs.writeFileSync(filePath, content, 'utf8');
13	}
14	
