17	function waitForMessage(socket: WebSocket): Promise<string> {
18	  return new Promise((resolve, reject) => {
19	    const timer = setTimeout(() => reject(new Error('Timed out waiting for WebSocket message')), 5000);
20	    socket.once('message', (data) => {
21	      clearTimeout(timer);
22	      resolve(data.toString());
23	    });
24	  });
25	}
26	
27	function waitForOpen(socket: WebSocket): Promise<void> {
28	  return new Promise((resolve, reject) => {
29	    socket.once('open', () => resolve());
30	    socket.once('error', reject);
31	  });
32	}
