import * as fs from 'fs';
import * as path from 'path';
import { parseFrontmatter } from '../src/frontmatter';
import { renderMarkdown } from '../src/render';
import type { Plugin, PluginContext } from '../src/plugin';
import type { Page } from '../src/types';

/**
 * Built-in plugin that turns each discovered Markdown file into a page:
 * parses its frontmatter, renders the Markdown body to HTML, and fills in
 * title/date/tags/layout metadata (falling back to the slug-derived title
 * when frontmatter omits one).
 */
export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  onFile(page: Page, ctx: PluginContext): Page {
    const filePath = path.join(ctx.contentDir, page.sourcePath);
    const raw = fs.readFileSync(filePath, 'utf8');
    const { data, content } = parseFrontmatter(raw);
    const html = renderMarkdown(content);

    const title = typeof data.title === 'string' && data.title.trim() ? data.title : page.slug;
    const date = typeof data.date === 'string' && data.date.trim() ? data.date : undefined;
    const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
    const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : undefined;

    return { ...page, title, date, tags, html, layout };
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { TemplateEngine } from '../src/templates';
import { renderIndexBodyHtml } from '../src/render';
import type { Plugin, PluginContext } from '../src/plugin';
import type { Page } from '../src/types';

const INDEX_LAYOUT_NAME = 'index';

/**
 * Built-in plugin that renders every page through its Handlebars layout and
 * writes the resulting HTML files, then generates and writes the `index.html`
 * listing page once all pages are known.
 */
export class TemplatePlugin implements Plugin {
  readonly name = 'template';

  private engine?: TemplateEngine;

  beforeBuild(ctx: PluginContext): void {
    this.engine = new TemplateEngine(ctx.templatesDir);
  }

  afterBuild(pages: Page[], ctx: PluginContext): void {
    const engine = this.requireEngine();

    fs.mkdirSync(ctx.outputDir, { recursive: true });

    for (const page of pages) {
      const outPath = path.join(ctx.outputDir, page.outputFile);
      fs.mkdirSync(path.dirname(outPath), { recursive: true });
      const html = engine.render(page.layout, {
        title: page.title,
        date: page.date,
        tags: page.tags,
        body: page.html,
      });
      fs.writeFileSync(outPath, html, 'utf8');
    }

    const indexLayout = engine.hasLayout(INDEX_LAYOUT_NAME) ? INDEX_LAYOUT_NAME : undefined;
    const indexHtml = engine.render(indexLayout, {
      title: 'All Pages',
      tags: [],
      body: renderIndexBodyHtml(pages),
    });
    fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), indexHtml, 'utf8');
  }

  private requireEngine(): TemplateEngine {
    if (!this.engine) {
      throw new Error('TemplatePlugin: beforeBuild must run before afterBuild');
    }
    return this.engine;
  }
}

import * as fs from 'fs';
import * as http from 'http';
import * as path from 'path';
import chokidar from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import type { Plugin, PluginContext } from '../src/plugin';
import type { Page } from '../src/types';

export interface DevServerStartOptions {
  outputDir: string;
  /** Directories to watch; a change in any of them triggers a rebuild. */
  watchPaths: string[];
  /** Port to listen on. Use 0 to let the OS assign an ephemeral port. */
  port: number;
  /** Delay (ms) between a watched file change and the triggered rebuild, to coalesce bursts of changes. */
  debounceMs: number;
  /** Invoked to rebuild the site; the resulting pages flow back through this plugin's afterBuild hook. */
  rebuild: () => void;
}

export interface DevServerHandle {
  port: number;
  url: string;
  close(): Promise<void>;
}

const LIVERELOAD_PATH = '/__livereload';

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
};

function liveReloadScript(): string {
  return `<script>
(function () {
  var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  var socket = new WebSocket(protocol + '//' + window.location.host + '${LIVERELOAD_PATH}');
  socket.addEventListener('message', function (event) {
    if (event.data === 'reload') {
      window.location.reload();
    }
  });
})();
</script>`;
}

function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, `${script}\n</body>`);
  }
  return `${html}\n${script}`;
}

/** Resolves a request path to a file within rootDir, refusing to escape it via `..` traversal. */
function resolveServablePath(rootDir: string, urlPath: string): string | undefined {
  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
  let filePath = path.normalize(path.join(rootDir, decoded));

  if (filePath !== rootDir && !filePath.startsWith(rootDir + path.sep)) {
    return undefined;
  }

  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
    filePath = path.join(filePath, 'index.html');
  }

  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    return undefined;
  }

  return filePath;
}

/**
 * Built-in plugin that serves the built site over HTTP with live reload.
 * As a `Plugin`, its `afterBuild` hook broadcasts a reload message to
 * connected browsers whenever a rebuild completes as part of the plugin
 * pipeline. The HTTP server, WebSocket server, and file watcher themselves
 * are a long-lived process spanning many rebuilds, so they're managed via
 * the dedicated `start()`/`close()` API below rather than the single-shot
 * `onStart`/`onEnd` hooks.
 */
export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private readonly clients = new Set<WebSocket>();

  afterBuild(_pages: Page[], _ctx: PluginContext): void {
    this.broadcastReload();
  }

  private broadcastReload(): void {
    for (const client of this.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  private requestListener(outputDir: string): http.RequestListener {
    return (req, res) => {
      const filePath = resolveServablePath(outputDir, req.url ?? '/');

      if (!filePath) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not found');
        return;
      }

      const ext = path.extname(filePath).toLowerCase();
      const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';

      if (ext === '.html') {
        const html = fs.readFileSync(filePath, 'utf8');
        res.writeHead(200, { 'Content-Type': contentType });
        res.end(injectLiveReload(html));
        return;
      }

      res.writeHead(200, { 'Content-Type': contentType });
      fs.createReadStream(filePath).pipe(res);
    };
  }

  /** Starts the HTTP server, WebSocket server, and file watcher, resolving once both are ready. */
  start(options: DevServerStartOptions): Promise<DevServerHandle> {
    const { outputDir, watchPaths, port, debounceMs, rebuild } = options;

    const wss = new WebSocketServer({ noServer: true });
    const httpServer = http.createServer(this.requestListener(outputDir));

    httpServer.on('upgrade', (req, socket, head) => {
      if (req.url !== LIVERELOAD_PATH) {
        socket.destroy();
        return;
      }
      wss.handleUpgrade(req, socket, head, (ws) => {
        this.clients.add(ws);
        ws.on('close', () => this.clients.delete(ws));
      });
    });

    let rebuildTimer: ReturnType<typeof setTimeout> | undefined;
    const scheduleRebuild = (): void => {
      if (rebuildTimer) clearTimeout(rebuildTimer);
      rebuildTimer = setTimeout(() => {
        rebuildTimer = undefined;
        try {
          rebuild();
        } catch (err) {
          // eslint-disable-next-line no-console
          console.error('Rebuild failed:', err instanceof Error ? err.message : err);
        }
      }, debounceMs);
    };

    const watcher = chokidar.watch(watchPaths, { ignoreInitial: true });
    watcher.on('add', scheduleRebuild);
    watcher.on('change', scheduleRebuild);
    watcher.on('unlink', scheduleRebuild);

    const watcherReady = new Promise<void>((resolve) => watcher.once('ready', resolve));
    const listening = new Promise<number>((resolve, reject) => {
      httpServer.once('error', reject);
      httpServer.listen(port, () => {
        httpServer.removeListener('error', reject);
        const address = httpServer.address();
        resolve(typeof address === 'object' && address ? address.port : port);
      });
    });

    const clients = this.clients;

    return Promise.all([listening, watcherReady]).then(([boundPort]) => ({
      port: boundPort,
      url: `http://localhost:${boundPort}`,
      close(): Promise<void> {
        if (rebuildTimer) clearTimeout(rebuildTimer);
        for (const client of clients) client.terminate();
        return watcher.close().then(
          () =>
            new Promise<void>((resolveClose, rejectClose) => {
              wss.close(() => {
                httpServer.close((err) => {
                  if (err) rejectClose(err);
                  else resolveClose();
                });
              });
            })
        );
      },
    }));
  }
}

import * as path from 'path';
import { SsgEngine } from './engine';
import { MarkdownPlugin } from '../plugins/markdown';
import { TemplatePlugin } from '../plugins/template';
import type { Page } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  /** Directory containing layouts/ and partials/ subdirectories. Defaults to ./templates relative to the current working directory. */
  templatesDir?: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

/** The default (non-plugin-configured) build pipeline: parse Markdown, then render it through templates. */
export function defaultBuildPlugins(): [MarkdownPlugin, TemplatePlugin] {
  return [new MarkdownPlugin(), new TemplatePlugin()];
}

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const templatesDir = options.templatesDir ?? path.resolve(process.cwd(), 'templates');

  const engine = new SsgEngine({
    contentDir,
    outputDir,
    templatesDir,
    plugins: defaultBuildPlugins(),
  });

  return engine.build();
}

import * as path from 'path';
import { SsgEngine } from './engine';
import { defaultBuildPlugins } from './generator';
import { DevServerPlugin } from '../plugins/dev-server';
import type { BuildOptions } from './generator';

export interface ServeOptions extends BuildOptions {
  /** Port to listen on. Use 0 to let the OS assign an ephemeral port. Defaults to 3000. */
  port?: number;
  /** Delay (ms) between a watched file change and the triggered rebuild, to coalesce bursts of changes. */
  debounceMs?: number;
}

export interface ServeHandle {
  port: number;
  url: string;
  close(): Promise<void>;
}

const DEFAULT_PORT = 3000;
const DEFAULT_DEBOUNCE_MS = 100;

/**
 * Starts a dev server that serves the built site from `outputDir`, rebuilds
 * whenever `contentDir` or `templatesDir` change, and pushes a live-reload
 * notification over WebSocket to connected pages so browsers refresh
 * automatically once the rebuild completes.
 */
export function serve(options: ServeOptions): Promise<ServeHandle> {
  const { contentDir, outputDir } = options;
  const templatesDir = options.templatesDir ?? path.resolve(process.cwd(), 'templates');
  const debounceMs = options.debounceMs ?? DEFAULT_DEBOUNCE_MS;

  const devServer = new DevServerPlugin();
  const engine = new SsgEngine({
    contentDir,
    outputDir,
    templatesDir,
    plugins: [...defaultBuildPlugins(), devServer],
  });

  engine.build();

  return devServer.start({
    outputDir,
    watchPaths: [contentDir, templatesDir],
    port: options.port ?? DEFAULT_PORT,
    debounceMs,
    rebuild: () => {
      engine.build();
    },
  });
}

import * as fs from 'fs';
import type { Plugin } from './plugin';

export interface SsgConfig {
  plugins?: Plugin[];
}

let tsLoaderRegistered = false;

/**
 * Registers ts-node so plain `require()` can load a raw .ts config file when
 * running outside a TypeScript-aware host (e.g. the compiled CLI). Under a
 * host that already understands .ts files (such as ts-jest during tests),
 * this is a harmless no-op.
 */
function ensureTypeScriptLoader(): void {
  if (tsLoaderRegistered) return;
  tsLoaderRegistered = true;
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    require('ts-node/register');
  } catch {
    // The current runtime may already be able to load .ts files without it.
  }
}

/**
 * Loads plugin configuration from an `ssg.config.ts` (or .js) file at
 * `configPath`. Returns an empty config when the file does not exist, so
 * callers can fall back to their own built-in defaults.
 */
export function loadConfig(configPath: string): SsgConfig {
  if (!fs.existsSync(configPath)) {
    return {};
  }

  if (configPath.endsWith('.ts')) {
    ensureTypeScriptLoader();
  }

  const resolved = require.resolve(configPath);
  delete require.cache[resolved];
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const loaded = require(resolved);
  const config: SsgConfig = loaded?.default ?? loaded;
  return config ?? {};
}

#!/usr/bin/env node
import { Command } from 'commander';
import * as path from 'path';
import { build, defaultBuildPlugins } from './generator';
import { serve } from './serve';
import { SsgEngine } from './engine';
import { loadConfig } from './config';
import { DevServerPlugin } from '../plugins/dev-server';
import type { Plugin } from './plugin';

const DEFAULT_SERVE_DEBOUNCE_MS = 100;

/** Resolves the plugin pipeline for a build: the configured plugins when --config is given and non-empty, otherwise the built-ins. */
function resolvePlugins(configOpt: string | undefined): Plugin[] {
  if (!configOpt) return defaultBuildPlugins();
  const config = loadConfig(path.resolve(process.cwd(), configOpt));
  return config.plugins && config.plugins.length > 0 ? config.plugins : defaultBuildPlugins();
}

export function createCli(): Command {
  const program = new Command();

  program
    .name('ssg')
    .description('A static site generator for Markdown content');

  program
    .command('build')
    .description('Generate the static site')
    .option('--content <dir>', 'content directory to read Markdown files from', './content')
    .option('--output <dir>', 'output directory to write the generated site to', './dist')
    .option('--templates <dir>', 'templates directory containing layouts/ and partials/', './templates')
    .option('--config <file>', 'path to a ssg.config.ts plugin config file (defaults to the built-in plugins)')
    .action((opts: { content: string; output: string; templates: string; config?: string }) => {
      const contentDir = path.resolve(process.cwd(), opts.content);
      const outputDir = path.resolve(process.cwd(), opts.output);
      const templatesDir = path.resolve(process.cwd(), opts.templates);

      const result = opts.config
        ? new SsgEngine({
            contentDir,
            outputDir,
            templatesDir,
            plugins: resolvePlugins(opts.config),
          }).build()
        : build({ contentDir, outputDir, templatesDir });

      // eslint-disable-next-line no-console
      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
    });

  program
    .command('serve')
    .description('Build the site, then serve it with live reload while watching for changes')
    .option('--content <dir>', 'content directory to read Markdown files from', './content')
    .option('--output <dir>', 'output directory to write the generated site to', './dist')
    .option('--templates <dir>', 'templates directory containing layouts/ and partials/', './templates')
    .option('--port <port>', 'port to serve the dev server on', '3000')
    .option('--config <file>', 'path to a ssg.config.ts plugin config file (defaults to the built-in plugins)')
    .action(
      async (opts: {
        content: string;
        output: string;
        templates: string;
        port: string;
        config?: string;
      }) => {
        const contentDir = path.resolve(process.cwd(), opts.content);
        const outputDir = path.resolve(process.cwd(), opts.output);
        const templatesDir = path.resolve(process.cwd(), opts.templates);
        const port = Number(opts.port);

        const handle = opts.config
          ? await serveWithConfig(opts.config, { contentDir, outputDir, templatesDir, port })
          : await serve({ contentDir, outputDir, templatesDir, port });

        // eslint-disable-next-line no-console
        console.log(`Dev server running at ${handle.url}`);
        // eslint-disable-next-line no-console
        console.log(`Watching ${opts.content} and ${opts.templates} for changes...`);
      }
    );

  return program;
}

async function serveWithConfig(
  configOpt: string,
  dirs: { contentDir: string; outputDir: string; templatesDir: string; port: number }
) {
  const plugins = resolvePlugins(configOpt);
  const devServer =
    plugins.find((plugin): plugin is DevServerPlugin => plugin instanceof DevServerPlugin) ??
    (() => {
      const created = new DevServerPlugin();
      plugins.push(created);
      return created;
    })();

  const engine = new SsgEngine({ ...dirs, plugins });
  engine.build();

  return devServer.start({
    outputDir: dirs.outputDir,
    watchPaths: [dirs.contentDir, dirs.templatesDir],
    port: dirs.port,
    debounceMs: DEFAULT_SERVE_DEBOUNCE_MS,
    rebuild: () => {
      engine.build();
    },
  });
}

export function run(argv: string[]): void {
  createCli().parse(argv);
}

if (require.main === module) {
  run(process.argv);
}

